-- DNSOne: RPZ for PowerDNS Recursor 4.9. Installed as /etc/powerdns/recursor.lua.
--
-- The RPZ file is generated by DNSOne (`dnsone-ctl rpz build`) from blocklists and rules in MySQL,
-- validated with named-checkzone, and loaded here. DNSOne reloads it with
-- `rec_control reload-lua-config`, which swaps the policy in without restarting the Recursor.
--
-- Every node (Phase 2 replicas too) builds these files itself from the shared MySQL.

-- Root trust anchor KSK-2024. The root zone has been signed with it since the October 2026
-- rollover, but Ubuntu 24.04's Recursor 4.9.3 only knows KSK-2017 (20326); without this line
-- every answer fails DNSSEC validation and clients get SERVFAIL.
-- Source: https://data.iana.org/root-anchors/root-anchors.xml
addTA(".", "38696 8 2 683d2d0acb8c9b712a1948b27f741219298d0a450d612c483af444a4c0fb2b16")

-- The RPZ zones DNSOne lists in zones.lua, in order: court-ordered blocking first (it wins over
-- everything), then per client group its Safe Search rewrites, its allow zone (allow rules and
-- allowlists, all passthru) and its block zone. The Default group's are dnsone-safe.rpz,
-- dnsone-allow.rpz and dnsone.rpz. The policy script (dnsone.lua) applies only the client's group's zones.
local EDE_TEXT = { [15] = "Blocked by DNSOne", [16] = "Blocked by court order" }
local function loadRpz(file, name, ede)
    local options = {
        policyName = name,
        -- Blocked answers expire quickly, so whitelisting takes effect within a minute.
        maxTTL = 60,
    }
    if ede then
        -- Policy actions (NXDOMAIN, NODATA, null IP, walled garden) come from the records in the file.
        -- RFC 8914 Extended DNS Errors tell capable clients why: 15 Blocked, 16 Censored (court orders).
        -- Only on block zones: the Recursor adds it to every hit of the zone, passthru included.
        options.extendedErrorCode = ede
        options.extendedErrorExtra = EDE_TEXT[ede]
    end
    rpzFile(file, options)
end
local ok, zones = pcall(dofile, "/var/lib/dnsone/rpz/zones.lua")
if not ok or type(zones) ~= "table" then
    -- Before the first build with groups (upgrade from 1.0): the single zone.
    zones = { { file = "/var/lib/dnsone/rpz/dnsone.rpz", name = "dnsone", blocked = true } }
end
for _, z in ipairs(zones) do
    local f = io.open(z.file, "r")
    if f ~= nil then
        f:close()
        -- 1.3 listings have no ede: blocked zones then carry 15.
        loadRpz(z.file, z.name, z.ede or (z.blocked ~= false and 15 or nil))
    end
end

-- Hosted zones are answered by the local BIND and are not signed by DNSOne. Skip DNSSEC validation
-- for them (negative trust anchors), so a zone that is private, not yet delegated, or has a stale
-- DS at its parent still resolves for customers. The zone generator keeps this file current and
-- updates the running Recursor with `rec_control add-nta` / `clear-nta`.
local nta = io.open("/var/lib/dnsone/recursor/negative-trust-anchors.txt", "r")
if nta ~= nil then
    for line in nta:lines() do
        local name = line:match("^%s*([%w%.%-_]+)%s*$")
        if name then addNTA(name, "DNSOne hosted zone") end
    end
    nta:close()
end

-- Query log: every answer goes to dnsone-querylog (protobuf over TCP, one connection per thread).
-- Messages are queued and dropped if the collector is down; DNS is never slowed by it.
protobufServer("127.0.0.1:4242", {
    logQueries = false,
    logResponses = true,
    maxQueuedEntries = 10000,
    reconnectWaitTime = 2,
})
